import 'dart:convert';
import 'package:flutter_test/flutter_test.dart';
import 'package:flutter_core/preference_sync/preference_sync_client.dart';
class RecoveryCache implements PreferenceCache {
 final data=<String,String>{};bool denied=false;void Function(String,String)? onWrite;
 @override Future<String?> read(String key)async=>data[key];
 @override Future<void> write(String key,String value)async{onWrite?.call(key,value);if(denied)throw StateError('quota');data[key]=value;}
 @override Future<void> remove(String key)async{data.remove(key);}
}
class RecoveryFixture {
 final binding=PreferenceBinding(scope:PreferenceScope('tenant','user','tenant_admin','live'),kind:'shortcuts',resource:'navigation',screenIds:['1','2']);
 final cache=RecoveryCache();int revision=3,ids=0;Object? document;bool lose=false,foreign=false;
 final requests=<Map<String,dynamic>>[],receipts=<String,Map<String,dynamic>>{};
 RecoveryFixture({String? raw='{bad',Object? saved=const {'version':1,'screenIds':['1']}}):document=saved{if(raw!=null)cache.data[binding.key]=raw;}
 Map<String,dynamic> clone(Object? value)=>jsonDecode(jsonEncode(value)) as Map<String,dynamic>;
 Map<String,dynamic> snapshot()=>{'version':1,'scope':foreign?PreferenceScope('tenant','foreign','tenant_admin','live').toJson():binding.scope.toJson(),'kind':'shortcuts','resource':'navigation','revision':revision,'document':document};
 Future<Object?> send(Map<String,dynamic> request)async{requests.add(clone(request));if(request['action']=='read')return clone(snapshot());final id=request['requestId'] as String;if(receipts.containsKey(id))return clone(receipts[id]);if(request['revision']!=revision)throw PreferenceFailure('revision_conflict',409,snapshot());revision++;document=null;final result=clone(snapshot());receipts[id]=result;if(lose){lose=false;throw const PreferenceFailure('offline');}return result;}
 PreferenceSyncClient client()=>PreferenceSyncClient(binding:binding,transport:send,cache:cache,uuid:()=> '00000000-0000-4000-8000-${(++ids).toString().padLeft(12,'0')}');
 List<Map<String,dynamic>> get archives=>[for(final e in cache.data.entries)if(e.key.contains('.quarantine.'))clone(jsonDecode(e.value))];
}
void main(){
 test('native recovery review is read only and exposes no invalid document',()async{final f=RecoveryFixture(),c=f.client();await c.load();final before=Map<String,String>.from(f.cache.data),p=await c.reviewRecovery();expect(p!['uncertain'],true);expect(p['canRestore'],false);expect(p['canReset'],true);expect(p.containsKey('document'),false);expect(f.cache.data,before);expect(f.requests.every((r)=>r['action']=='read'),true);c.dispose();});
 test('native reset preserves corrupt bytes before CAS reset and independent read',()async{final f=RecoveryFixture(),c=f.client();await c.load();final p=(await c.reviewRecovery())!;await c.confirmRecovery(p['token'] as String,'reset');expect(f.archives.single['raw'],'{bad');expect((f.archives.single['server'] as Map)['document'],{'version':1,'screenIds':['1']});expect(f.revision,4);expect(c.current['status'],'clean');expect((c.current['base'] as Map)['document'],isNull);expect(f.requests.last['action'],'read');c.dispose();});
 test('native local corruption without pending can restore without cloud mutation',()async{final raw=jsonEncode({'pending':null,'broken':true}),f=RecoveryFixture(raw:raw),c=f.client();await c.load();final p=(await c.reviewRecovery())!;expect(p['canRestore'],true);await c.confirmRecovery(p['token'] as String,'restore');expect(c.current['status'],'clean');expect((c.current['draft'] as Map)['screenIds'],['1']);expect(f.requests.every((r)=>r['action']=='read'),true);expect(f.archives.single['raw'],raw);c.dispose();});
 test('native revoked cloud reference is quarantined and never applied',()async{final f=RecoveryFixture(raw:null,saved:{'version':1,'screenIds':['99']}),c=f.client();await c.load();final p=(await c.reviewRecovery())!;expect(p['canRestore'],false);await c.confirmRecovery(p['token'] as String,'reset');expect(f.document,isNull);expect(c.current['status'],'clean');expect(((f.archives.single['server'] as Map)['document'] as Map)['screenIds'],['99']);c.dispose();});
 test('native cancel and unconfirmed actions preserve original record',()async{final f=RecoveryFixture(),c=f.client();await c.load();final p=(await c.reviewRecovery())!;await expectLater(c.confirmRecovery('other','reset'),throwsA(isA<PreferenceFailure>()));c.cancelRecovery();await expectLater(c.confirmRecovery(p['token'] as String,'reset'),throwsA(isA<PreferenceFailure>()));expect(f.cache.data[f.binding.key],'{bad');expect(f.archives,isEmpty);c.dispose();});
 test('native changed cache or server version invalidates review',()async{for(final target in ['server','cache']){final f=RecoveryFixture(),c=f.client();await c.load();final p=(await c.reviewRecovery())!;if(target=='server'){f.revision++;}else{f.cache.data[f.binding.key]='new draft';}await expectLater(c.confirmRecovery(p['token'] as String,'reset'),throwsA(isA<PreferenceFailure>().having((e)=>e.code,'code','recovery_changed')));expect(f.archives,isEmpty);expect(f.requests.every((r)=>r['action']=='read'),true);c.dispose();}});
 test('native scope mismatch and backup denial send no reset',()async{final f=RecoveryFixture(),c=f.client();await c.load();f.foreign=true;await expectLater(c.reviewRecovery(),throwsA(isA<PreferenceFailure>()));expect(f.archives,isEmpty);f.foreign=false;final p=(await c.reviewRecovery())!;f.cache.denied=true;await expectLater(c.confirmRecovery(p['token'] as String,'reset'),throwsA(isA<PreferenceFailure>().having((e)=>e.code,'code','cache_unavailable')));expect(f.cache.data[f.binding.key],'{bad');expect(f.requests.every((r)=>r['action']=='read'),true);c.dispose();});
 test('native lost reset acknowledgement replays original UUID after reload',()async{final f=RecoveryFixture(),c=f.client();await c.load();final p=(await c.reviewRecovery())!;f.lose=true;await c.confirmRecovery(p['token'] as String,'reset');final original=f.requests.firstWhere((r)=>r['action']=='reset');c.dispose();final reload=f.client();await reload.load();await reload.retryPending();expect(f.requests.where((r)=>r['action']=='reset').toList(),[original,original]);expect(f.revision,4);expect(reload.current['pending'],isNull);expect(f.archives.single['raw'],'{bad');reload.dispose();});
 test('native unknown request is archived but never replayed',()async{final raw=jsonEncode({'pending':{'requestId':'old-unknown','document':{'screenIds':['99']}}}),f=RecoveryFixture(raw:raw),c=f.client();await c.load();final p=(await c.reviewRecovery())!;await c.confirmRecovery(p['token'] as String,'reset');expect(f.archives.single['raw'],raw);expect(f.requests.any((r)=>r['requestId']=='old-unknown'),false);expect(f.revision,4);c.dispose();});
 test('native disposal and concurrent tab edits during backup are preserved',()async{for(final dispose in [true,false]){final f=RecoveryFixture(),c=f.client();await c.load();final p=(await c.reviewRecovery())!;f.cache.onWrite=(key,value){if(key.contains('.quarantine.')){if(dispose){c.dispose();}else{f.cache.data[f.binding.key]='other tab';}}};if(dispose){await c.confirmRecovery(p['token'] as String,'reset');}else{await expectLater(c.confirmRecovery(p['token'] as String,'reset'),throwsA(isA<PreferenceFailure>()));}expect(f.cache.data[f.binding.key],dispose?'{bad':'other tab');expect(f.requests.every((r)=>r['action']=='read'),true);expect(f.archives.single['raw'],'{bad');if(!dispose)c.dispose();}});
}
